for (const line of lines) {
  const req = JSON.parse(line);
  try {
    if (req.op === 'enc') {
      const s = req.cps.map((c) => String.fromCodePoint(c)).join('');
      out.push({ ok: true, s: punycodeEncode(s) });
    } else {
      const res = punycodeDecode(req.s);
      out.push({ ok: true, cps: Array.from(res, (c) => c.codePointAt(0)) });
    }
  } catch (e) {
    out.push({ ok: false, err: `${e.name}: ${e.message}` });
  }
